    """根据模式获取文件列表"""
    path = Path(directory)

    # 如果模式包含通配符，使用 glob
    if '*' in pattern or '?' in pattern:
        return sorted(path.glob(pattern))
    else:
        # 尝试作为正则表达式
        try:
            regex = re.compile(pattern)
            return sorted([f for f in path.iterdir() 
                          if f.is_file() and regex.search(f.name)])
        except re.error:
            # 如果正则无效，使用简单通配符匹配
            return sorted(path.glob(f"*{pattern}*"))

