        print(f"✗ {old_path.name}: {e}")
        failed += 1

print(f"\n完成: {success} 成功, {failed} 失败")

if args.include_empty:
    empty_files = [
        f for f in Path(args.directory).rglob('*')
        if not f.is_symlink() and f.is_file() and f.stat().st_size == 0
    ]
    if empty_files:
        print(f"\n发现 {len(empty_files)} 个空文件 (空文件不参与自动去重操作):")
        for ef in empty_files:
            print(f"  {ef}")

for file_hash, files in duplicates.items():
    keep_file = select_keep_file(files, args.keep)

    for f in files:
        if f == keep_file:
            continue

        try:
            if args.action == 'delete':
                f.unlink()
                print(f"删除: {f}")
            elif args.action == 'move' and args.to:
                target = quarantine_path / f.name
                counter = 1
                while target.exists():
                    target = quarantine_path / f"{f.stem}_{counter}{f.suffix}"
                    counter += 1
                shutil.move(str(f), str(target))
                print(f"移动: {f} → {target}")
            processed += 1
        except Exception as e:
            print(f"错误: 无法处理 {f}: {e}")

print(f"\n完成: 处理了 {processed} 个重复文件")

# 显示操作
for action, src, tgt in actions[:20]:
    if action == 'copy':
        print(f"[复制] {src.relative_to(source_path)} → {tgt.relative_to(target_path)}")
    elif action == 'update':
        print(f"[更新] {tgt.relative_to(target_path)}")
    elif action == 'delete':
        print(f"[删除] {tgt.relative_to(target_path)}")

if len(actions) > 20:
    print(f"... 还有 {len(actions) - 20} 个操作")

print(f"\n总计: {len([a for a in actions if a[0] != 'delete'])} 个文件需要同步")
print(f"       {len([a for a in actions if a[0] == 'delete'])} 个文件将被删除")

for action, src, tgt in actions:
    try:
        tgt.parent.mkdir(parents=True, exist_ok=True)

        if action == 'copy':
            shutil.copy2(src, tgt)
            stats['copied'] += 1
            print(f"复制: {src.name}")
        elif action == 'update':
            shutil.copy2(src, tgt)
            stats['updated'] += 1
            print(f"更新: {tgt.name}")
        elif action == 'delete':
            tgt.unlink()
            stats['deleted'] += 1
            print(f"删除: {tgt.name}")
    except Exception as e:
        print(f"错误: {e}")

print(f"\n同步完成: {stats['copied']} 复制, {stats['updated']} 更新, "
      f"{stats['deleted']} 删除, {stats['skipped']} 跳过")
